 const normal=value=>{let n=normalizedFood(value);for(const [a,b] of [['llenties','lentejas'],['cigrons','garbanzos'],['arros','arroz'],['verdures','verduras'],['patates','patata'],['truita','tortilla'],['pollastre','pollo'],['pastanaga','zanahoria'],['iogurt','yogur'],['amb','con'],['forn','horno']])n=n.replace(new RegExp('\\b'+a+'\\b','g'),b);return n;};
