 for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(quoted){quoted=false;closed=true;}else if(!cell&&!closed)quoted=true;else throw Error('Comillas CSV no válidas.');}else if(!quoted&&(c===delimiter||c==='\n'||c==='\r')){row.push(cell);cell='';closed=false;if(c!==delimiter){if(c==='\r'&&text[i+1]==='\n')i++;if(row.some(x=>x.trim()))rows.push(row);row=[];}}else if(closed){if(!/[ \t]/.test(c))throw Error('Hay texto después de una celda entre comillas. Revisa el CSV.');}else cell+=c;if(cell.length>5000||row.length>12||rows.length>32)throw Error('La tabla escolar es demasiado grande.');}
