 if(headers.some(x=>!x)||new Set(headers).size!==headers.length||!headers.includes('date'))throw Error('Cabecera: fecha;tipo_dia;primero;segundo;guarnicion;postre;otros;observaciones.');
 return rows.map(row=>{if(row.length!==headers.length)throw Error('Una fila no tiene el mismo número de columnas que la cabecera.');const data=Object.fromEntries(headers.map((k,n)=>[k,row[n].trim()]));let date=data.date;if(/^\d{2}\/\d{2}\/\d{4}$/.test(date))date=date.slice(6)+'-'+date.slice(3,5)+'-'+date.slice(0,2);const types={colegio:'school',school:'school',casa:'home',home:'home',festivo:'home',desconocido:'unknown',unknown:'unknown'};let kind=data.kind?types[normalizedFood(data.kind)]:null;if(data.kind&&!kind)throw Error('Tipo de día: colegio, casa o desconocido.');const components=SCHOOL_ROLES.filter(([key])=>data[key]).map(([role])=>({role,name:data[role]}));kind=kind||(components.length?'school':'unknown');return {date,kind,components,notes:data.notes||'',complete:['si','true','1'].includes(normalizedFood(data.complete||''))};});
