 for(let day=0;day<7;day++)for(const [slot] of SLOTS){const m=candidate.days[day][slot],outside=!onlyWeek&&addDays(week,day).slice(0,7)!==month,keep=outside||m.locked||m.external||mode==='fill'&&old.kind!=='demo'&&!!m.recipeId;if(keep){m.locked=true;preserved.add(day+'|'+slot);}}
