function schoolPlanStatus(record){if(!record)return 'Sin información';if(record.kind==='home')return 'Come en casa';if(record.kind==='unknown')return 'Sin información';const n=record.components.filter(c=>c.reviewed&&c.entries.length).length;return n===record.components.length&&n&&record.complete?'Composición orientativa':n?'Datos parciales':'Platos sin cuantificar';}
function schoolSettingsMarkup(p){return `<div class="school-config"><div class="field"><label for="school-mode">Cómo usar el menú del colegio</label><select name="schoolMode" id="school-mode"><option value="record" ${p?.schoolMode!=='complement'?'selected':''}>Registro manual plato por plato</option><option value="complement" ${p?.schoolMode==='complement'?'selected':''}>Automático con Tabla Excel/CSV</option></select>${schoolModeHintMarkup(p?.schoolMode)}<small>La complementación tiene en cuenta los platos escolares al preparar las comidas de casa. Los menús guardados se conservan.</small></div><label class="feature-row"><span><b>Usar cantidades orientativas del colegio</b><small>Solo con «Automático con Tabla Excel/CSV» y correspondencias revisadas. No son cantidades medidas ni consumidas.</small><small class="school-estimates-note">${icon('info')}En modo automático, desactivar esta opción impide calcular los valores nutricionales estimados de las comidas del colegio. Los datos registrados con cantidades propias se conservan.</small></span><input type="checkbox" class="switch" name="schoolEstimates" ${p?.schoolEstimates?'checked':''}/></label></div>`;}
function schoolPanel(){
 if(!profile().school)return '';const month=state.week.slice(0,7),records=schoolMonthDates(month).map(d=>schoolPlanAt(d)).filter(r=>r?.kind==='school'),pending=records.filter(r=>!r.complete||r.components.some(c=>!c.reviewed||!c.entries.length)).length;
 return `<section class="surface panel-pad school-panel"><div class="subheading"><div><h2>Menú del colegio</h2><p>${h(MONTHS[+month.slice(5)-1])} ${month.slice(0,4)} · ${schoolComplement()?'Automático con Tabla Excel/CSV':'Registro manual plato por plato'}</p></div>${icon('calendar')}</div><p>${records.length} días cargados${pending?' · '+pending+' con información parcial':''}. Las comidas del colegio no se añaden a la compra.</p><div class="toolbar"><button type="button" class="btn primary" data-action="school-calendar">Ver mes</button><button type="button" class="btn outline" data-action="school-import">Cargar menú</button></div><div class="school-list">${DAYS.flatMap((name,day)=>SCHOOL_SLOTS.filter(s=>schoolMeal(day,s)).map(s=>{const record=schoolRecord(day,s);return `<button type="button" class="school-entry" data-action="school-log" data-day="${day}" data-slot="${s}"><strong>${name} ${parseDate(addDays(state.week,day)).getDate()} · ${h(slotLabel(s))}</strong><span>${h(record.text||'Sin información')}</span><small>${h(record.source)}</small></button>`;})).join('')}</div></section>`;
}
function schoolDialog(body,title='Menú del colegio',wide=false){return `<div class="modal-scrim" data-action="scrim"><div class="modal ${wide?'school-wide':''}" role="dialog" aria-modal="true" aria-label="${h(title)}"><div class="modal-head"><h2>${h(title)}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Cerrar ventana">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="btn outline" data-action="close-modal">Cerrar</button></div></div></div>`;}
function schoolCalendarMarkup(month){
 const dates=schoolMonthDates(month),offset=(parseDate(dates[0]).getDay()+6)%7,library=Object.entries(state.schoolDishes||{}).filter(([k])=>k.startsWith(state.activeProfile+'|'));
 return schoolDialog(`<div class="field"><label for="school-month">Mes del menú</label><input type="month" id="school-month" data-action="school-month" min="2000-01" max="2099-12" value="${h(month)}"/></div><div class="toolbar"><button class="btn primary" data-action="school-import" data-month="${month}">Cargar menú</button><button class="btn outline" data-action="school-export" data-month="${month}">Exportar mes</button><button class="btn outline" data-action="school-pattern" data-month="${month}">Repetir una semana</button></div><p>Revisa cada fecha. Un hueco no se interpreta como festivo. Registrar el menú no cambia las comidas de casa.</p><div class="school-calendar">${DAYS.map(n=>`<b class="school-weekday">${n.slice(0,3)}</b>`).join('')}${Array.from({length:offset},()=>'<span class="school-spacer"></span>').join('')}${dates.map(date=>{const r=schoolPlanAt(date);return `<button type="button" class="school-date ${r?.kind==='school'?'school-loaded':''}" data-action="school-edit-date" data-date="${date}"><b>${DAYS[(parseDate(date).getDay()+6)%7].slice(0,3)} ${+date.slice(-2)}</b>${schoolNames(r)?`<span>${h(schoolNames(r))}</span>`:''}<small>${h(schoolPlanStatus(r))}</small></button>`;}).join('')}</div>${schoolComplement()?`<div class="selected-surface"><strong>Preparar comidas de casa</strong><p>Las comidas fijadas y externas se conservan. «Completar huecos» conserva también las demás comidas guardadas. Los días fuera del mes se mantienen.</p><div class="toolbar"><button class="btn primary" data-action="school-generate" data-month="${month}" data-mode="fill">Completar huecos del mes</button><button class="btn outline" data-action="school-generate-preview" data-month="${month}">Regenerar tomas no fijadas…</button></div></div>`:'<p>Para tener en cuenta este menú al generar, elige «Automático con Tabla Excel/CSV» en el perfil.</p>'}<details class="family-recipe"><summary>Platos del colegio guardados · ${library.length}</summary><p>Correspondencias privadas reutilizables. Una receta genérica no describe necesariamente la receta del comedor.</p>${library.map(([key,c])=>`<div class="school-library-row"><span><b>${h(c.name)}</b><small>${h(schoolTemplate(c.templateId)?.name||'Cantidades aportadas')} · ${c.entries.length} ingredientes</small></span><button type="button" class="btn outline" data-action="school-forget" data-key="${h(key)}">Olvidar</button></div>`).join('')||'<p>Se guardan al revisar e importar platos con referencias.</p>'}</details>`, 'Menú del colegio',true);
}
function schoolImportMarkup(month){return schoolDialog(`<form id="school-import-form"><div class="field"><label for="school-import-month">Mes y año del documento</label><input type="month" name="month" id="school-import-month" value="${month}" min="2000-01" max="2099-12" required/></div><div class="field"><label for="school-file">Archivo de menú escolar, Excel o CSV</label><input type="file" id="school-file" data-action="school-file" accept=".xlsx,.json,.csv,.tsv,text/csv,application/json,text/tab-separated-values"/></div><div class="field"><label for="school-paste">O pega una tabla de Excel / CSV</label><textarea id="school-paste" name="text" rows="7" maxlength="1048576" placeholder="fecha;tipo_dia;primero;segundo;guarnicion;postre;otros;observaciones"></textarea></div><p>Si solo tienes una foto, puedes enviarla en tu chat para obtener un archivo de Menú escolar y cargarlo aquí. Revisa siempre fechas y platos. La app no analiza imágenes directamente.</p><button type="button" class="btn outline" data-action="school-template-xlsx">Descargar plantilla Excel</button><button type="button" class="btn outline" data-action="school-template">Descargar plantilla CSV</button><p class="form-error" id="school-import-error" role="status"></p><button class="btn primary" type="submit">Revisar importación</button></form>`,'Cargar menú del colegio');}
function schoolPreviewComponentMarkup(c){return `<div class="school-preview-component"><p><b>${h(SCHOOL_ROLES.find(([k])=>k===c.role)[1])}:</b> ${h(c.name)}<small class="school-component-note">${c.templateId?'Referencia propuesta: '+h(schoolTemplate(c.templateId)?.name||'')+' · '+c.entries.length+' ingrediente'+(c.entries.length===1?'':'s')+' estimado'+(c.entries.length===1?'':'s'):c.entries.length?'Cantidades aportadas · revisar alimento y estado':'Sin cantidades · solo texto y grupos reconocidos'}</small></p>${c.entries.length?`<details><summary>Ver composición orientativa y cantidades</summary>${c.entries.map(e=>`<p>${h(NUTRITION_BY_ID[e.foodId].label)} · ${fmtNum(e.grams)} g · ${h(NUTRITION_BY_ID[e.foodId].weightState)}</p>`).join('')}</details>`:''}</div>`;}
function schoolPreviewMarkup(){
 if(!pendingSchool||pendingSchool.profileId!==state.activeProfile)return schoolDialog('<p>La importación ha caducado. Vuelve a cargar el archivo.</p>');
 return schoolDialog(`<form id="school-confirm-form"><p>${h(pendingSchool.month)} · ${pendingSchool.days.length} fecha${pendingSchool.days.length===1?'':'s'}. Las fechas que ya tenían menú están desmarcadas: selecciónalas solo si quieres actualizarlas. Los registros de lo servido se conservan.</p>${pendingSchool.days.map((day,n)=>`<div class="school-preview-row"><label class="feature-row"><input type="checkbox" data-action="school-take" data-index="${n}" ${day.take?'checked':''}/><span><b>${h(day.date)} · ${h(day.kind==='home'?'Come en casa':day.kind==='unknown'?'Sin información':'Colegio')}</b><small>${schoolPlanAt(day.date)?'Ya hay un menú guardado · actualizar es opcional':'Fecha nueva'}</small></span></label>${day.components.map(schoolPreviewComponentMarkup).join('')}${day.kind==='school'?`<label class="school-complete"><input type="checkbox" data-action="school-complete" data-index="${n}" ${day.complete?'checked':''}/> Incluye toda la comida anunciada, con bebida y acompañamientos cuando proceda</label>`:''}<p>${h(day.notes)}</p><button type="button" class="btn outline" data-action="school-review-row" data-index="${n}">Revisar / editar fecha</button></div>`).join('')}<label class="feature-row"><input type="checkbox" name="confirmed" required/><span>He revisado fechas, platos y correspondencias. Acepto las cantidades orientativas de las referencias seleccionadas; no son mediciones del comedor.</span></label><p class="form-error" id="school-confirm-error" role="status"></p><button type="submit" class="btn primary">Guardar fechas seleccionadas</button></form>`,'Revisar menú del colegio',true);
}
function schoolRowMarkup(index){
 const record=pendingSchool?.days[index];if(!record)return schoolDialog('<p>Fecha no disponible.</p>');const options=schoolRecipeOptions(),components=[...record.components];if(components.length<8)components.push({name:'',role:'other',templateId:'',portion:1,entries:[]});
 return schoolDialog(`<form id="school-row-form" data-index="${index}"><p><b>${h(record.date)}</b>. Elige una referencia solo si sus ingredientes representan razonablemente el plato. Puedes dejarlo sin cuantificar.</p><div class="field"><label for="school-kind">Tipo de día</label><select name="kind" id="school-kind">${[['school','Colegio'],['home','Come en casa'],['unknown','Sin información']].map(([k,v])=>`<option value="${k}" ${record.kind===k?'selected':''}>${v}</option>`).join('')}</select><small>Al elegir casa o sin información se retiran los componentes escolares de esta fecha.</small></div>${components.map((c,n)=>`<fieldset class="school-component"><legend>Componente ${n+1}</legend><div class="field"><label for="school-name-${n}">Nombre del plato / alimento</label><input id="school-name-${n}" name="name-${n}" value="${h(c.name)}" maxlength="180" list="school-known-dishes"/></div><div class="form-row"><div class="field"><label for="school-role-${n}">Parte de la comida</label><select id="school-role-${n}" name="role-${n}">${SCHOOL_ROLES.map(([k,v])=>`<option value="${k}" ${c.role===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="school-portion-${n}">Factor de cantidad orientativa</label><input id="school-portion-${n}" type="number" min="0.25" max="2" step="0.05" name="portion-${n}" value="${c.portion||1}"/><small>1 = propuesta del modelo para esta parte de la comida; no es una ración oficial.</small></div></div><div class="field"><label for="school-ref-${n}">Preparación comparable</label><select id="school-ref-${n}" name="template-${n}"><option value="">Solo texto / sin referencia</option>${options.map(r=>`<option value="${h(r.baseRecipeId)}" ${c.templateId===r.baseRecipeId?'selected':''}>${h(r.name)}</option>`).join('')}</select></div>${c.entries?.length?`<details><summary>${c.entries.length} ingredientes de la referencia · ver / editar gramos</summary><p>Pesos en el estado de cada referencia; no son peso final cocinado. Cambiar gramos conserva estos valores como cantidades aportadas.</p>${c.entries.map((e,j)=>`<div class="field"><label><input type="checkbox" name="include-${n}-${j}" checked/> Incluir este ingrediente</label><label for="school-entry-${n}-${j}">${h(NUTRITION_BY_ID[e.foodId].label)} · ${h(NUTRITION_BY_ID[e.foodId].weightState||'estado de la referencia')}</label><input type="number" id="school-entry-${n}-${j}" name="grams-${n}-${j}" min="0.1" max="5000" step="any" value="${e.grams}"/></div>`).join('')}</details>`:''}</fieldset>`).join('')}<datalist id="school-known-dishes">${Object.entries(state.schoolDishes||{}).filter(([k])=>k.startsWith(state.activeProfile+'|')).map(([,c])=>`<option value="${h(c.name)}"></option>`).join('')}</datalist><div class="field"><label for="school-notes">Observaciones</label><textarea id="school-notes" name="notes" maxlength="1500">${h(record.notes)}</textarea></div><label><input type="checkbox" name="complete" ${record.complete?'checked':''}/> Incluye toda la comida anunciada</label><p class="form-error" id="school-row-error" role="status"></p><button class="btn primary" type="submit">Aplicar y volver a la revisión</button></form>`,'Revisar '+record.date,true);
}
function schoolSaveRow(form){
 const d=new FormData(form),index=+form.dataset.index,old=pendingSchool?.days[index];if(!old||pendingSchool.profileId!==state.activeProfile)throw Error('El perfil ha cambiado.');const components=[];
 for(let n=0;n<8;n++){const name=String(d.get('name-'+n)||'').trim();if(!name)continue;const previous=old.components[n],chosen=String(d.get('template-'+n)||''),portion=Number(d.get('portion-'+n)||1);let c={name,role:String(d.get('role-'+n)||'other'),templateId:chosen,portion,entries:[],reviewed:false};
  if(previous&&previous.name===name&&previous.templateId===chosen&&previous.portion===portion){c={...previous,...c,entries:previous.entries.flatMap((e,j)=>d.has('include-'+n+'-'+j)?[{...e,grams:Number(d.get('grams-'+n+'-'+j)||e.grams)}]:[])};if(JSON.stringify(c.entries)!==JSON.stringify(previous.entries)){c.amountSource='provided';c.basis=previous.basis;}else{c.amountSource=previous.amountSource;c.basis=previous.basis;}}
  // La selección explícita «sin referencia» prevalece sobre la biblioteca.
  components.push(schoolValidateComponent(c));
 }
 const kind=String(d.get('kind'));let record=schoolValidateRecord({kind,components:kind==='school'?components:[],notes:String(d.get('notes')||''),complete:d.has('complete')});record.components=record.components.map(c=>schoolResolveComponent(c,record));pendingSchool.days[index]={date:old.date,...record,take:true};state.modal={type:'school-preview'};render();
}
function schoolStartDate(date){
 const old=schoolPlanAt(date)||{kind:'school',components:[],complete:false,notes:''};pendingSchool={profileId:state.activeProfile,month:date.slice(0,7),days:[{date,...JSON.parse(JSON.stringify(old)),take:true}]};state.modal={type:'school-row',index:0};render();
}
function schoolDownload(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function schoolExport(month){const days=schoolMonthDates(month).filter(d=>schoolPlanAt(d)).map(date=>({date,...schoolPlanAt(date)}));schoolDownload(JSON.stringify({app:'menu-infantil-colegio',formatVersion:1,month,days},null,2),'menu-colegio-'+month+'.json','application/json');}
function schoolPatternMarkup(month){return schoolDialog(`<form id="school-pattern-form"><input type="hidden" name="month" value="${month}"/><p>Copia los días escolares de una semana guardada a otras fechas del mes. Las fechas existentes quedan desmarcadas para conservarlas en la revisión.</p><div class="field"><label for="pattern-week">Una fecha de la semana que quieres repetir</label><input type="date" id="pattern-week" name="source" required/></div><div class="field"><label for="pattern-from">Desde</label><input type="date" id="pattern-from" name="from" value="${month}-01" required/></div><div class="field"><label for="pattern-to">Hasta</label><input type="date" id="pattern-to" name="to" value="${schoolMonthDates(month).at(-1)}" required/></div><p class="form-error" id="school-pattern-error" role="status"></p><button class="btn primary">Revisar fechas repetidas</button></form>`,'Repetir una semana');}
function schoolRecordMarkup(day,slot){const record=schoolRecord(day,slot);return `<div class="selected-surface"><strong>${h(record.source)}</strong><p>${h(record.text||'Sin información')}</p>${record.estimated?'<p>Estimación de ingredientes y cantidades; no indica lo consumido. '+(record.complete?'Todos los componentes marcados están cuantificados.':'Composición parcial: falta información.')+'</p>':''}${record.stale?'<p class="form-error">La estimación corresponde a otros datos del perfil. Revisa la fecha del calendario.</p>':''}${record.entries.length?`<details><summary>Ver cantidades del colegio</summary>${record.entries.map(e=>`<p>${h(NUTRITION_BY_ID[e.foodId].label)} · ${fmtNum(e.grams)} g · ${h(NUTRITION_BY_ID[e.foodId].weightState||'estado de referencia')}</p>`).join('')}</details>`:''}${slot==='lunch'?`<button type="button" class="btn outline" data-action="school-edit-date" data-date="${addDays(state.week,day)}">Editar menú previsto de esta fecha</button>`:''}</div>`;}
function schoolGenerationPreview(month){return schoolDialog(`<p>Se prepararán las semanas que contienen fechas de <b>${h(month)}</b>. Solo cambiarán las tomas de casa no fijadas dentro del mes. Se conservarán las comidas externas y los días de otros meses.</p><p>Esta opción puede sustituir comidas que ya hayas elegido. Para conservarlas, utiliza «Completar huecos del mes».</p><button class="btn primary" data-action="school-generate" data-month="${month}" data-mode="replace">Regenerar tomas no fijadas del mes</button>`,'Revisar preparación del mes');}
function installSchoolCalendar(){
 const previousClose=closeModal;closeModal=function(){pendingSchool=null;schoolReadToken++;return previousClose();};
 try{Object.assign(state,schoolValidateState(state,state.profiles));}catch{state.schoolPlans={};state.schoolDishes={};}
 schoolMeal=function(day,slot,p=profile()){return schoolMealForDate(addDays(state.week,day),slot,p);};
 schoolText=function(day,slot='lunch'){const record=schoolRecord(day,slot);return record.text+(record.estimated?' · ≈ estimación':'');};
 renderSchool=schoolPanel;
 const oldProfile=renderProfileForm;renderProfileForm=function(p){return oldProfile(p).replace('</fieldset><div id="profile-error"',schoolSettingsMarkup(p)+'</fieldset><div id="profile-error"');};
 const oldModal=renderModal;renderModal=function(){const m=state.modal;if(m?.type==='school-calendar')return schoolCalendarMarkup(m.month);if(m?.type==='school-import')return schoolImportMarkup(m.month);if(m?.type==='school-preview')return schoolPreviewMarkup();if(m?.type==='school-row')return schoolRowMarkup(m.index);if(m?.type==='school-pattern')return schoolPatternMarkup(m.month);if(m?.type==='school-generate-preview')return schoolGenerationPreview(m.month);return oldModal();};
 const oldSchoolModal=schoolModal;schoolModal=function(day,slot='lunch'){return schoolRecordMarkup(day,slot)+oldSchoolModal(day,slot).replace('Registro de esta toma. No cambia las demás comidas.','Registro de lo servido. Si difiere del menú previsto, su estimación deja de representar esta toma.').replace('nunca se añade a la compra ni se compensan automáticamente las otras tomas.','nunca se añade a la compra. Con «Automático con Tabla Excel/CSV», los datos conocidos se utilizan en las siguientes propuestas.');};
 const oldGenerate=renderGenerate;renderGenerate=function(){let html=oldGenerate();const pos=html.indexOf('<button class="btn outline" data-action="blank-week"');if(pos<0)return html;const blocked=familyBlock(),buttons=`<button class="btn outline" data-action="school-complete-week" ${!schoolComplement()||blocked?'disabled':''}>${icon('plus')}Completar huecos de la semana</button>${profile().school?`<button class="btn outline" data-action="school-calendar">${icon('calendar')}Ver menú del colegio</button>`:''}${schoolComplement()?`<button class="btn outline" data-action="school-generate" data-mode="fill" data-month="${state.week.slice(0,7)}" ${blocked?'disabled':''}>${icon('calendar')}Completar huecos del mes · ${h(MONTHS[+state.week.slice(5,7)-1])}</button>`:''}`;html=html.slice(0,pos)+buttons+html.slice(pos);return html.replace('Colegio: registra cada toma y sus cantidades para completar el día.','Se utiliza el menú escolar disponible para preparar las comidas de casa. Las estimaciones y la información pendiente se muestran por separado.');};
 const oldReview=dayNutritionReview;dayNutritionReview=function(day){const review=oldReview(day);if(!profile().school)return review;for(const [slot] of activeMeals())if(schoolMeal(day,slot)){const record=schoolRecord(day,slot);if(record.estimated){review.notes.push(slotLabel(slot)+': composición escolar estimada, no consumo medido.');if(!record.complete){review.complete=false;review.pending.push(slotLabel(slot)+' del colegio: información parcial o estimación desactualizada');}}}return review;};
 const oldBalance=renderBalanceReview;renderBalanceReview=function(){let html=oldBalance();if(schoolComplement()&&menu().schoolBasis&&menu().schoolBasis!==schoolWeekSignature())html=html.replace('<h2>Revisión nutricional de la propuesta</h2>','<h2>Revisión nutricional de la propuesta</h2><p class="form-error">Ha cambiado el menú del colegio o su configuración. Las comidas de casa se han conservado; revisa o vuelve a preparar las tomas que correspondan.</p>');return html;};
 const oldBackup=backupEnvelope;backupEnvelope=function(){const result=oldBackup();result.data.schoolPlans=state.schoolPlans||{};result.data.schoolDishes=state.schoolDishes||{};return result;};
 const oldValidate=validateBackup;validateBackup=function(input){const result=oldValidate(input);for(let n=0;n<result.profiles.length;n++){const raw=input.data.profiles[n];if(raw.schoolMode!=null&&!['record','complement'].includes(raw.schoolMode)||raw.schoolEstimates!=null&&typeof raw.schoolEstimates!=='boolean')throw Error('Configuración escolar no válida.');result.profiles[n].schoolMode=raw.schoolMode||'record';result.profiles[n].schoolEstimates=raw.schoolEstimates===true;}Object.assign(result,schoolValidateState(input.data,result.profiles));for(const [key,m] of Object.entries(result.menus)){const basis=input.data.menus[key].schoolBasis;if(basis!=null){if(typeof basis!=='string'||!/^[a-f0-9]{1,8}$/.test(basis))throw Error('Referencia de menú escolar no válida.');m.schoolBasis=basis;}}return result;};
}
document.addEventListener('click',event=>{
 const el=event.target.closest?.('[data-action]');if(!el)return;const a=el.dataset.action,month=el.dataset.month||state.week.slice(0,7);
 if(a==='scrim'&&event.target!==el)return;
 if(a==='school-calendar'){pendingSchool=null;schoolReadToken++;openModal('school-calendar',{month});}
 if(a==='school-import'){pendingSchool=null;schoolReadToken++;openModal('school-import',{month});}
 if(a==='school-edit-date')schoolStartDate(el.dataset.date);
 if(a==='school-review-row')openModal('school-row',{index:+el.dataset.index});
 if(a==='school-export')schoolExport(month);
 if(a==='school-template'){const m=document.getElementById('school-import-month')?.value||month;schoolDownload('\uFEFFfecha;tipo_dia;primero;segundo;guarnicion;postre;otros;observaciones\r\n'+schoolMonthDates(m).filter(d=>(parseDate(d).getDay()+6)%7<5).map(d=>d+';desconocido;;;;;;').join('\r\n'),'plantilla-colegio-'+m+'.csv','text/csv;charset=utf-8');}
 if(a==='school-template-xlsx')downloadSchoolExcel(document.getElementById('school-import-month')?.value||month);
 if(a==='school-pattern')openModal('school-pattern',{month});
 if(a==='school-generate-preview')openModal('school-generate-preview',{month});
 if(a==='school-generate')schoolGenerateRange(month,el.dataset.mode);
 if(a==='school-complete-week')schoolGenerateRange(month,'fill',true);
 if(a==='school-forget'){const next={...state,schoolDishes:{...state.schoolDishes}};delete next.schoolDishes[el.dataset.key];if(commitUserState(next)){render();notify('Correspondencia retirada de la biblioteca. El calendario se conserva.');}}
 if(['close-modal','scrim','nav','select-profile'].includes(a)){pendingSchool=null;schoolReadToken++;}
});
document.addEventListener('change',async event=>{
 const el=event.target,a=el.dataset?.action;
 if(a==='school-month'){if(schoolMonthValid(el.value))openModal('school-calendar',{month:el.value});return;}
 if(a==='school-take'||a==='school-complete'){const row=pendingSchool?.days[+el.dataset.index];if(row)row[a==='school-take'?'take':'complete']=el.checked;return;}
 if(a==='school-file'){const file=el.files?.[0],token=++schoolReadToken,pid=state.activeProfile;try{if(!file)return;const excel=/\.xlsx$/i.test(file.name||'');if(!excel&&file.size>1024*1024)throw Error('El archivo supera el límite de 1 MB.');const text=excel?await readSchoolExcel(file):await file.text();if(token!==schoolReadToken||pid!==state.activeProfile||state.modal?.type!=='school-import')return;document.getElementById('school-paste').value=text;document.getElementById('school-import-error').textContent='Archivo leído. Pulsa «Revisar importación».';}catch(e){if(token!==schoolReadToken||pid!==state.activeProfile||state.modal?.type!=='school-import')return;const node=document.getElementById('school-import-error');if(node)node.textContent=e.message;}return;}
 if(a==='select-profile-input'){pendingSchool=null;schoolReadToken++;}
});
document.addEventListener('submit',event=>{
 const form=event.target;if(!['school-import-form','school-confirm-form','school-row-form','school-pattern-form'].includes(form.id))return;event.preventDefault();try{
  const data=new FormData(form);
  if(form.id==='school-import-form'){pendingSchool=schoolParseImport(String(data.get('text')||''),String(data.get('month')));openModal('school-preview');}
  if(form.id==='school-confirm-form')schoolCommitImport(pendingSchool,data.has('confirmed'));
  if(form.id==='school-row-form')schoolSaveRow(form);
  if(form.id==='school-pattern-form'){const month=String(data.get('month')),from=String(data.get('from')),to=String(data.get('to')),source=String(data.get('source'));if(!schoolDate(source)||!schoolDate(from)||!schoolDate(to)||from>to||from.slice(0,7)!==month||to.slice(0,7)!==month)throw Error('Revisa las fechas y el mes de destino.');const start=startWeek(parseDate(source)),days=schoolMonthDates(month).filter(d=>d>=from&&d<=to).flatMap(date=>{const day=(parseDate(date).getDay()+6)%7,record=schoolPlanAt(addDays(start,day));return record?[{date,...JSON.parse(JSON.stringify(record)),take:!schoolPlanAt(date)}]:[];});if(!days.length)throw Error('La semana de origen no tiene platos guardados para esas fechas.');pendingSchool={profileId:state.activeProfile,month,days};openModal('school-preview');}
 }catch(e){const ids={'school-import-form':'school-import-error','school-confirm-form':'school-confirm-error','school-row-form':'school-row-error','school-pattern-form':'school-pattern-error'},node=document.getElementById(ids[form.id]);if(node)node.textContent=e.message;}
});
